/**
 * Milestone domain rules that need no database: the state-conflict error,
 * name comparison, the overdue test and the listing order.
 *
 * `MilestoneService` owns the guards; this module only answers questions
 * about values already loaded, so the same rules can be reused by the UI.
 */
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

const DEFAULT_MESSAGES: Readonly<Record<MilestoneStateReason, string>> = {
  closed: "That milestone is closed.",
  already_open: "That milestone is already open.",
  too_many_open: "This project already has the maximum number of open milestones.",
  name_taken: "Another milestone in this project already uses that name.",
};

/** A milestone in the wrong state for the requested change; maps to `conflict`. */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly reason: MilestoneStateReason,
    message: string = DEFAULT_MESSAGES[reason],
  ) {
    super(message);
    this.name = "MilestoneStateError";
  }
}

export function isMilestoneOpen(milestone: Pick<Milestone, "closedAt">): boolean {
  return milestone.closedAt === null;
}

/** Names collide without regard to letter case or surrounding spaces. */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

export function isMilestoneNameTaken(
  name: string,
  existing: readonly Pick<Milestone, "id" | "name">[],
  ignoreId: Milestone["id"] | null = null,
): boolean {
  const key = milestoneNameKey(name);
  return existing.some(
    (milestone) =>
      milestone.id !== ignoreId && milestoneNameKey(milestone.name) === key,
  );
}

/**
 * Open, with a target date strictly in the past and work still open. A
 * milestone without a target date is never overdue.
 */
export function isMilestoneOverdue(
  milestone: Pick<Milestone, "closedAt" | "targetDate">,
  progress: MilestoneProgress,
  now: Date = new Date(),
): boolean {
  if (!isMilestoneOpen(milestone) || milestone.targetDate === null) {
    return false;
  }
  return (
    new Date(milestone.targetDate).getTime() < now.getTime() &&
    progress.open > 0
  );
}

/**
 * Listing order: open before closed; then by target date, earliest first,
 * undated last. Equal keys keep their incoming order, so callers pass rows
 * already in creation order.
 */
export function compareMilestones(
  a: Pick<Milestone, "closedAt" | "targetDate">,
  b: Pick<Milestone, "closedAt" | "targetDate">,
): number {
  const openA = isMilestoneOpen(a);
  const openB = isMilestoneOpen(b);
  if (openA !== openB) return openA ? -1 : 1;

  if (a.targetDate === null || b.targetDate === null) {
    if (a.targetDate === b.targetDate) return 0;
    return a.targetDate === null ? 1 : -1;
  }

  return new Date(a.targetDate).getTime() - new Date(b.targetDate).getTime();
}

