/**
 * Milestone rows plus the issue-side bookkeeping a milestone owns: progress
 * counts and the bulk move of open issues when one is closed.
 *
 * Must call (do not reimplement): livePredicate, orgPredicate
 */
import { and, asc, count, eq, inArray, isNull, notInArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { brandId, toMilestone } from "./_mappers";
import type {
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

const EMPTY_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/**
 * Every milestone of a project, open and closed, in creation order. `rowid`
 * breaks ties between rows stamped in the same millisecond.
 */
export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .orderBy(asc(milestones.createdAt), sql`rowid`)
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMilestone(
  input: CreateMilestoneInput,
): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      targetDate: input.targetDate ?? null,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMilestone(row);
}

export async function updateMilestone(
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(input.name === undefined ? {} : { name: input.name }),
