/**
 * Milestone lifecycle inside a project: unique naming, the open-milestone cap, closing with the move of open issues, and progress.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import {
  MilestoneStateError,
  compareMilestones,
  isMilestoneNameTaken,
  isMilestoneOpen,
  isMilestoneOverdue,
} from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  NotFoundError,
  actorEnvelope,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";
import type { Project } from "@/types/project";

/**
 * Closing a milestone alerts the assignees of the issues it moved, and that
 * alert is the notification fan-out's reaction to `milestone.closed`. Loading
 * the fan-out here means a process that can close milestones can tell people.
 */
import "./notification-service";

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  // Names stay reserved by closed milestones too, so check every one.
  const existing = await milestoneRepo.listMilestonesForProject(
    input.orgId,
    project.id,
  );
  if (isMilestoneNameTaken(input.name, existing)) {
    throw new MilestoneStateError("name_taken");
  }
  if (
    existing.filter(isMilestoneOpen).length >= MAX_OPEN_MILESTONES_PER_PROJECT
  ) {
    throw new MilestoneStateError("too_many_open");
  }

  const milestone = await milestoneRepo.insertMilestone(input);

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

/** Renames and re-dates apply to closed milestones as well as open ones. */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  const { milestone } = await loadMilestoneForWrite(
    actor,
    input.orgId,
    input.milestoneId,
  );

  if (input.name !== undefined) {
    const existing = await milestoneRepo.listMilestonesForProject(
      input.orgId,
      milestone.projectId,
    );
    if (isMilestoneNameTaken(input.name, existing, milestone.id)) {
      throw new MilestoneStateError("name_taken");
    }
  }

  return milestoneRepo.updateMilestone(input);
}

/**
 * Closes an open milestone. Its open live issues move to `moveOpenIssuesTo`
 * — another open milestone of the same project — or out of any milestone
 * when none is named. Every check runs before the first write, so a refused
 * close changes nothing and publishes nothing.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  const { milestone } = await loadMilestoneForWrite(
    actor,
    input.orgId,
    input.milestoneId,
  );
  if (!isMilestoneOpen(milestone)) {
    throw new MilestoneStateError("closed");
  }

  const moveTo = input.moveOpenIssuesTo ?? null;
  if (moveTo !== null) {
    const target =
      moveTo === milestone.id
        ? null
        : await milestoneRepo.findMilestoneById(input.orgId, moveTo);
    if (target === null || target.projectId !== milestone.projectId) {
      throw new NotFoundError("Milestone", moveTo);
    }
    if (!isMilestoneOpen(target)) {
      throw new MilestoneStateError("closed");
    }
  }

  const closed = await milestoneRepo.closeMilestone(
    input.orgId,
    milestone.id,
    moveTo,
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.milestone.id,
    projectId: closed.milestone.projectId,
    movedToMilestoneId: moveTo,
    movedIssueIds: closed.movedIssueIds,
  });

  return closed;
}

/** Reopening counts against the open-milestone cap like creating does. */
export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const { milestone } = await loadMilestoneForWrite(actor, orgId, milestoneId);
  if (isMilestoneOpen(milestone)) {
    throw new MilestoneStateError("already_open");
  }

  const open = await milestoneRepo.countOpenMilestones(
    orgId,
    milestone.projectId,
  );
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }

  const reopened = await milestoneRepo.reopenMilestone(orgId, milestone.id);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

/**
 * Open milestones first, then closed; within each, earliest target date
 * first with undated ones last; ties in creation order. Works for archived
 * projects too — only writes are refused there.
