    "Milestone",
    milestoneId,
  );
  const project = await requireProjectOf(milestone);
  assertCan(actor, "project:read", projectResource(project));

  const progress = await milestoneRepo.getMilestoneProgress(orgId, [
    milestone.id,
  ]);

  return withProgress(milestone, progress[milestone.id], new Date());
}

