  cleanup = await useTemporaryDatabase();
  t = await createTenant("ms");
  other = await createTenant("ms-other");
  registerActivityListeners();
});
afterAll(() => cleanup());

const past = "2020-01-01T00:00:00.000Z" as IsoTimestamp;
const future = "2099-01-01T00:00:00.000Z" as IsoTimestamp;

describe("milestones", () => {
  it("creates, enforces names and cap, lists in order", async () => {
    const proj = await projectService.createProject(t.actors.admin, { orgId: t.org.id, name: "MS proj", slug: "ms-proj", key: "MSP", description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null });
    const a = await ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: proj.id, name: "Alpha", targetDate: null });
    expect(a.closedAt).toBeNull();
    await expect(ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: proj.id, name: "  ALPHA ", targetDate: null })).rejects.toMatchObject({ reason: "name_taken" });
    await expect(ms.createMilestone(t.actors.viewer, { orgId: t.org.id, projectId: proj.id, name: "V", targetDate: null })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(ms.createMilestone(other.actors.owner, { orgId: t.org.id, projectId: proj.id, name: "V", targetDate: null })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(ms.createMilestone(other.actors.owner, { orgId: other.org.id, projectId: proj.id, name: "V", targetDate: null })).rejects.toBeInstanceOf(NotFoundError);
    // same name ok in another project
    await ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: t.project.id, name: "alpha", targetDate: null });
    const b = await ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: proj.id, name: "Beta", targetDate: future });
    const c = await ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: proj.id, name: "Gamma", targetDate: past });
    const d = await ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: proj.id, name: "Delta", targetDate: null });
    for (let i = 0; i < 6; i++) await ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: proj.id, name: `M${i}`, targetDate: null });
    await expect(ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: proj.id, name: "Eleven", targetDate: null })).rejects.toMatchObject({ reason: "too_many_open", code: "conflict" });
    // close one, then create works; reopen refused when full
    await ms.closeMilestone(t.actors.member, { orgId: t.org.id, milestoneId: d.id, moveOpenIssuesTo: null });
    const e = await ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: proj.id, name: "Epsilon", targetDate: null });
    await expect(ms.reopenMilestone(t.actors.member, t.org.id, d.id)).rejects.toMatchObject({ reason: "too_many_open" });
    await expect(ms.reopenMilestone(t.actors.member, t.org.id, e.id)).rejects.toMatchObject({ reason: "already_open" });
    await expect(ms.closeMilestone(t.actors.member, { orgId: t.org.id, milestoneId: d.id, moveOpenIssuesTo: null })).rejects.toMatchObject({ reason: "closed" });
    // closed name stays reserved
