rm -f /tmp/ms-check/mig.mts && cat > /tmp/ms-check/mig.test.ts <<'EOF'
import { expect, it } from "vitest";
import Database from "better-sqlite3";
import { rmSync } from "node:fs";
import { runMigrations } from "@/server/db/migrate";
it("upgrades an old issues table", async () => {
  const path = "/tmp/ms-check/old.db";
  rmSync(path, { force: true });
  const old = new Database(path);
  old.exec("CREATE TABLE issues (id TEXT PRIMARY KEY NOT NULL, org_id TEXT NOT NULL, project_id TEXT NOT NULL, number INTEGER NOT NULL, title TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT, status TEXT, assignee_id TEXT, due_at TEXT)");
  old.close();
  await runMigrations(path);
  await runMigrations(path);
  const db = new Database(path);
  const cols = (db.pragma("table_info(issues)") as { name: string }[]).map((c) => c.name);
  const objs = (db.prepare("SELECT name FROM sqlite_master WHERE name LIKE '%milestone%'").all() as { name: string }[]).map((r) => r.name);
  db.close();
  expect(cols).toContain("milestone_id");
  expect(objs.sort()).toEqual(["issues_org_milestone_idx", "milestones", "milestones_org_project_idx"]);
});
EOF
NO_COLOR=1 npx vitest run --config /tmp/ms-check/vitest.config.mjs 2>&1 | grep -v "npm warn" | tail -8

